icons.eye='<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>';icons.scan='<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 9h10M7 13h10m-10 4h6"/>';icons.spark='<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>';icons.chevron='<path d="m9 5 7 7-7 7"/>';icons.food='<path d="M5 3v7m3-7v7M2 3v7c0 4 6 4 6 0M5 14v8M17 3c-5 4-5 11 0 11V3Zm0 11v8"/>';icons.bag='<path d="M4 8h16l1 13H3ZM8 8V6a4 4 0 0 1 8 0v2"/>';icons.play='<path d="m9 5 10 7-10 7Z"/>';icons.filter='<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>';
const ic=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.leaf}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const defaults={posts:[],connections:[],receipts:[],project:'Projeto Sementes',reflection:'',completed:[],notify:false,notifyTime:'07:00',events:[],favorites:[],hideImpact:false,profile:{name:'Mariana Oliveira',business:'',city:'Recife, PE'}};
let state;try{state={...structuredClone(defaults),...JSON.parse(localStorage.getItem('cris-app-v1')||'{}')}}catch{state=structuredClone(defaults)}
function save(){try{localStorage.setItem('cris-app-v1',JSON.stringify(state))}catch{toast('Seu navegador não permitiu salvar as alterações.')}}
let route='inicio',filter='Todos',query='',toastTimer,onlyFavorites=false,pendingCategory=null;
const nav=[['inicio','home','Início'],['empresas','store','Empresas'],['mural','mural','Mural de oportunidades'],['conexoes','connect','Minhas conexões'],['comunidade','calendar','Comunidade e eventos'],['cursos','course','Cursos e capacitação'],['biblia','book','Bíblia e reflexão'],['impacto','heart','Meu impacto']];
const businesses=[{id:'pao',name:'Pão & Prosa',category:'Alimentação',city:'Recife, PE',tag:'5% para projetos',art:'coffee',image:true,initial:'P',desc:'Pães artesanais, café passado na hora e boas conversas. Um pequeno negócio que acolhe o bairro há oito anos.',products:'Pães de fermentação natural, cafés e encomendas',owner:'Beatriz Santos',rate:5,hours:'Seg–sáb, 7h às 18h'},{id:'raizes',name:'Estúdio Raízes',category:'Serviços',city:'Recife, PE',tag:'8% para projetos',art:'roots',initial:'r.',desc:'Design com identidade para marcas que têm uma história para contar. Estratégia, criação e cuidado em cada detalhe.',products:'Identidade visual, embalagens e comunicação digital',owner:'Lucas Almeida',rate:8,hours:'Seg–sex, 9h às 18h'},{id:'esperanca',name:'Espaço Esperança',category:'Saúde',city:'Olinda, PE',tag:'3% para projetos',art:'health',initial:'e',desc:'Cuidado com escuta, acolhimento e atenção à pessoa. Um espaço de saúde para toda a família.',products:'Fisioterapia e acompanhamento nutricional',owner:'Ana Costa',rate:3,hours:'Seg–sex, 8h às 17h'}];
const samplePosts=[{id:'s1',type:'Preciso',title:'Uma identidade nova para meu negócio',description:'Estou abrindo uma confeitaria e procuro alguém para criar a identidade visual e as embalagens.',author:'Beatriz Santos',area:'Design · Recife',initial:'B'},{id:'s2',type:'Posso oferecer',title:'30 minutos para organizar suas finanças',description:'Sou contador e ofereço uma conversa inicial para empresários que querem separar as contas pessoais das contas da empresa.',author:'Daniel Lima',area:'Finanças · Online',initial:'D'},{id:'s3',type:'Preciso',title:'Fornecedor de embalagens sustentáveis',description:'Buscamos embalagens de papel para entregas de alimentos. Tem alguém na comunidade para indicar?',author:'Pedro Rocha',area:'Alimentação · Olinda',initial:'P'},{id:'s4',type:'Posso oferecer',title:'Fotografia que valoriza seu produto',description:'Faço fotografia de produtos para pequenos negócios. Vamos conversar sobre o que sua marca precisa?',author:'Camila Alves',area:'Fotografia · Recife',initial:'C'}];
const courses=[{id:'gestao',title:'Finanças com propósito',category:'GESTÃO DO NEGÓCIO',desc:'Dê o primeiro passo para separar contas, entender seu caixa e planejar.',icon:'chart',lessons:[['Separe as contas','Separar o dinheiro da empresa do dinheiro pessoal torna suas decisões mais claras. Defina uma retirada planejada e registre cada entrada e saída.','Liste três despesas pessoais que hoje se misturam às despesas da empresa.'],['Enxergue seu caixa','O fluxo de caixa acompanha quando o dinheiro entra e quando sai. Antes de assumir um compromisso, observe os próximos recebimentos e pagamentos.','Monte uma lista de entradas e saídas previstas para os próximos sete dias.'],['Planeje o próximo passo','Uma meta pequena e acompanhada vale mais do que uma intenção ampla. Escolha uma melhoria, um prazo e uma forma simples de medir o avanço.','Defina uma meta para o próximo mês e o primeiro passo para alcançá-la.']]},{id:'marca',title:'Sua marca, sua história',category:'MARKETING E VENDAS',desc:'Comunique o valor do que você faz e crie relações de confiança.',icon:'store',lessons:[['O que você resolve?','Uma boa apresentação começa pela necessidade do cliente. Descreva com simplicidade quem você atende e qual problema ajuda a resolver.','Escreva uma frase: ajudo [pessoa] a [resultado] por meio de [serviço].'],['Uma promessa possível','Confiança nasce da coerência entre o que se promete e o que se entrega. Use exemplos concretos do seu trabalho.','Escolha um projeto que demonstre sua principal qualidade.']]},{id:'lideranca',title:'Liderar para servir',category:'LIDERANÇA E VALORES',desc:'Princípios para construir uma equipe com escuta, clareza e cuidado.',icon:'leaf',lessons:[['Comece pela escuta','Servir também é compreender o que a outra pessoa precisa para trabalhar bem. Faça perguntas, escute e combine próximos passos claros.','Pergunte a alguém da sua equipe: o que posso fazer para facilitar seu trabalho?'],['Clareza também é cuidado','Combinados claros reduzem insegurança. Explique o objetivo, ouça as dúvidas e registre o que foi acordado.','Revise um combinado e confirme se todos o entenderam da mesma forma.']]}];
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function heading(label,title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
const goButton=(r,text,icon='arrow',cls='btn')=>`<button class="${cls}" data-route="${r}">${text}${ic(icon)}</button>`;
function art(b){return `<div class="biz-art ${b.art}">${b.image?'<img src="assets/comercio-cris.webp" alt="Pequeno comércio ilustrativo">':b.art==='roots'?'<div class="design-scene" aria-hidden="true"><i>ra.</i><span>RAÍZES<br>ESTÚDIO CRIATIVO</span><b></b></div>':'<div class="health-scene" aria-hidden="true"><i>e.</i><span>espaço<br>esperança</span><b></b></div>'}<span class="biz-tag">${ic('heart')} ${b.rate}% de impacto</span></div>`}
function bizCard(b){const fav=(state.favorites||[]).includes(b.id);return `<article class="business-card"><div class="biz-visual"><button class="biz-open-art" data-business="${b.id}" aria-label="Conhecer ${b.name}">${art(b)}</button><button class="favorite ${fav?'is-saved':''}" data-favorite="${b.id}" aria-label="${fav?'Remover':'Salvar'} ${b.name}" aria-pressed="${fav}">${ic('heart')}</button></div><button class="biz-info" data-business="${b.id}" aria-label="Ver perfil de ${b.name}"><div class="biz-meta"><span>${b.category}</span><span>${ic('pin')} ${b.city.split(',')[0]}</span></div><h3>${b.name}</h3><p>${b.id==='pao'?'Pães artesanais & boas conversas':b.id==='raizes'?'Design para marcas com história':'Cuidado que acolhe você'}</p><div class="biz-bottom"><span class="partner-dot"></span>Negócio da comunidade<span>${ic('arrow')}</span></div></button></article>`}
function wordCard(){return `<section class="word-card"><div class="word-top"><span class="word-book">${ic('book')}</span><span>Um respiro no seu dia<small>PALAVRA & REFLEXÃO</small></span>${ic('spark')}</div><blockquote>“Tudo o que fizerem,<br>façam de todo o coração.”</blockquote><cite>Colossenses 3:23 · Trecho</cite><p class="practice">Um convite para colocar mais cuidado no que você faz hoje.</p>${goButton('biblia','Ler e refletir','arrow','text-btn')}</section>`}
function home(){const name=esc(state.profile.name.split(' ')[0]);const latest=state.receipts[0];return `<section class="daily-header"><div class="daily-welcome"><div><span>Bom ter você aqui,</span><h1>${name} <span>☀</span></h1></div><button data-action="location" class="daily-location">${ic('pin')}<span>Explorando em<strong>${esc(state.profile.city.split(',')[0])} ⌄</strong></span></button></div><div class="daily-impact"><div><span class="impact-label">Seu impacto social <button class="pass-eye" data-action="toggle-impact" aria-label="${state.hideImpact?'Mostrar':'Ocultar'} valor do impacto">${ic('eye')}</button></span><button data-route="impacto" class="daily-balance">${state.hideImpact?'••••••':'R$ 248,90'} ${ic('chevron')}</button><span class="impact-growth">${ic('chart')} + R$ 38,50 neste mês <small>Exemplo</small></span></div><button class="project-medallion" data-route="impacto" aria-label="Ver projeto apoiado">${ic('leaf')}<span>Seu bem<br>floresce aqui</span></button></div><div class="daily-actions">${[['nota','scan','Enviar nota'],['impacto','heart','Meu impacto'],['conexoes','connect','Conexões'],['cursos','course','Aprender'],['biblia','book','Palavra']].map(([r,i,t])=>`<button data-route="${r}"><span>${ic(i)}</span>${t}</button>`).join('')}</div></section><div class="daily-feed"><form class="home-search" id="home-search-form">${ic('search')}<input name="q" placeholder="O que você procura hoje?" aria-label="Buscar na CRIS"><button aria-label="Buscar empresas" type="submit">${ic('arrow')}</button></form><div class="service-rail">${[['Alimentação','food','Comer bem'],['Serviços','bag','Serviços'],['Saúde','heart','Bem-estar'],['Todos','store','Ver tudo']].map(([c,i,t],j)=>`<button data-category="${c}"><span class="service-picture service-${j}">${ic(i)}</span><strong>${t}</strong></button>`).join('')}</div><div class="moment-rail"><button class="moment-card moment-faith" data-route="biblia"><span class="moment-label">${ic('spark')} PALAVRA DO DIA</span><strong>Faça de todo<br>o coração.</strong><span class="moment-foot">Colossenses 3:23 <i>${ic('arrow')}</i></span></button><button class="moment-card moment-community" data-route="mural"><img src="assets/hero-comunidade-v4.webp" alt=""><span class="moment-label">SUA REDE, MAIS PERTO</span><strong>Uma boa conexão<br>muda o seu dia.</strong><span class="moment-foot">Explorar o mural <i>${ic('arrow')}</i></span></button></div><div class="carousel-position" aria-hidden="true"><i></i><i></i></div><section class="daily-discovery"><div class="section-head"><div><h2>Seu bairro tem coisa boa</h2><p>Descubra quem empreende perto de você.</p></div>${goButton('empresas','Ver todos','chevron','text-btn')}</div><div class="business-grid home-businesses">${businesses.map(bizCard).join('')}</div></section><button class="receipt-reminder" data-route="${latest?'impacto':'nota'}"><span class="receipt-icon">${ic('receipt')}</span><span><strong>${latest?'Sua nota está em análise':'Comprou em uma empresa parceira?'}</strong><small>${latest?esc(latest.business)+' · Acompanhe a contribuição':'Envie a nota e transforme sua compra em apoio.'}</small></span>${ic('chevron')}</button><section class="daily-network"><div class="section-head"><div><h2>Gente que soma com você</h2><p>Troque ideias. Encontre oportunidades.</p></div>${goButton('mural','Abrir','chevron','text-btn')}</div><article class="network-post"><div class="network-person"><span class="avatar">B</span><span><strong>Beatriz Santos</strong><small>Confeitaria artesanal · Recife</small></span><span class="badge">Preciso</span></div><h3>Minha confeitaria está crescendo.<br>Quem me ajuda com a nova marca?</h3><div class="network-footer"><span>${ic('connect')} Design & identidade visual</span><button data-connect="s1">Conectar ${ic('arrow')}</button></div></article></section><div class="learn-mini"><span class="learn-art">${ic('course')}</span><div><small>15 MINUTOS PARA CRESCER</small><strong>Seu negócio merece esse cuidado.</strong><span>Comece por Finanças com propósito.</span><button data-course="gestao">Começar trilha ${ic('arrow')}</button></div></div><button class="project-strip" data-route="impacto"><span>${ic('leaf')}</span><div><small>SEU PROJETO ESCOLHIDO</small><strong>${esc(state.project)}</strong><p>Veja o caminho de cada contribuição.</p></div>${ic('chevron')}</button><p class="daily-demo">Ambiente de demonstração · Dados ilustrativos</p></div>`}

function market(){return heading('PERTO DE VOCÊ','Explorar','Encontre seu próximo lugar favorito.')+`<div class="toolbar"><label class="search">${ic('search')}<input id="market-search" type="search" placeholder="Empresa, produto ou serviço" aria-label="Buscar empresa, produto ou serviço" value="${esc(query)}"></label><button class="filter-button ${onlyFavorites?'selected':''}" data-action="filter-favorites" aria-label="${onlyFavorites?'Mostrar todas as empresas':'Mostrar empresas salvas'}" aria-pressed="${onlyFavorites}">${ic('heart')}</button></div><div class="market-location">${ic('pin')} ${esc(state.profile.city)} <span>Empresas de demonstração</span></div><div class="chips category-filters" aria-label="Categorias">${[['Todos','store'],['Alimentação','food'],['Serviços','bag'],['Saúde','heart']].map(([c,i])=>`<button class="chip ${filter===c?'selected':''}" data-filter="${c}" aria-pressed="${filter===c}">${ic(i)}${c}</button>`).join('')}</div><div class="market-explainer"><span class="mini-spark">${ic('spark')}</span><span><strong>Você compra. A empresa contribui.</strong><small>Parte da compra apoia um projeto. Sem pagar a mais.</small></span></div><div class="section-head"><h2>${onlyFavorites?'Seus negócios salvos':'Feitos para descobrir'}</h2><span class="results-note">${ic('leaf')} Com propósito</span></div><div class="business-grid market-grid" id="market-results">${marketResults()}</div><details class="flow-details"><summary>Como a compra vira impacto? ${ic('plus')}</summary><p>Encontre uma empresa, compre diretamente com ela e envie a nota pela CRIS. Após a validação, acompanhe a contribuição ao projeto escolhido. Percentuais e empresas de demonstração.</p></details>`}

function marketResults(){const q=query.toLocaleLowerCase('pt-BR');const found=businesses.filter(b=>(!onlyFavorites||(state.favorites||[]).includes(b.id))&&(filter==='Todos'||b.category===filter)&&(b.name+' '+b.category+' '+b.products).toLocaleLowerCase('pt-BR').includes(q));return found.length?found.map(bizCard).join(''):'<div class="empty">Nenhuma empresa encontrada. Tente outro termo ou categoria.</div>'}
function mural(){return heading('SUA COMUNIDADE','Mural','De que você precisa hoje?' ,`<button class="btn" data-action="new-post">Publicar ${ic('plus')}</button>`)+`<div class="sample-banner">Mural demonstrativo. Suas publicações ficam salvas somente neste navegador.</div><div class="chips">${['Todos','Preciso','Posso oferecer'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-post-filter="${t}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div><div class="mural-grid">${[...state.posts,...samplePosts].filter(p=>filter==='Todos'||p.type===filter).map(p=>`<article class="panel post"><span class="badge ${p.type==='Posso oferecer'?'offer':''}">${esc(p.type)}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="post-footer"><div class="person"><span class="avatar">${esc(p.initial)}</span><span>${esc(p.author)}<small>${esc(p.area)}</small></span></div><button class="text-btn" ${p.id.startsWith("p")?"disabled":""} data-connect="${esc(p.id)}">${p.id.startsWith("p")?"Sua publicação":state.connections.some(c=>c.postId===p.id)?'Ver conexão':'Tenho interesse'} ${ic('arrow')}</button></div></article>`).join('')||'<div class="empty">Ainda não há publicações nesta categoria.</div>'}</div>`}
function connections(){const count=s=>state.connections.filter(c=>c.status===s).length;return heading('DA CONVERSA À OPORTUNIDADE','Sua rede em movimento.','Acompanhe indicações, reuniões e negócios da sua rede.')+`<div class="stats"><div class="panel stat"><small>Conexões iniciadas</small><strong>${state.connections.length}</strong></div><div class="panel stat"><small>Reuniões marcadas</small><strong>${count('Reunião marcada')}</strong></div><div class="panel stat"><small>Negócios gerados</small><strong>${count('Negócio gerado')}</strong></div></div><div class="sample-banner">Registrar interesse cria uma conexão local de demonstração. Nenhuma mensagem é enviada.</div>${state.connections.length?state.connections.map(c=>`<article class="panel connection"><span class="avatar">${esc(c.person[0])}</span><div class="connection-info"><h3>${esc(c.person)}</h3><p>${esc(c.title)}</p></div><label><span class="eyebrow">Etapa da conexão</span><select data-status="${esc(c.id)}" aria-label="Etapa da conexão com ${esc(c.person)}">${['Interesse registrado','Indicação feita','Reunião marcada','Negócio gerado'].map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('')}</select></label></article>`).join(''):`<div class="panel empty"><h2>Sua próxima parceria começa no mural.</h2><p>Encontre uma necessidade que você pode atender e registre seu interesse.</p>${goButton('mural','Explorar oportunidades')}</div>`}`}
function coursePage(){return heading('NO SEU RITMO','Aprender','Pequenos passos para fortalecer seu negócio.')+`<div class="sample-banner">Trilhas de demonstração com pequenas leituras e exercícios. Os conteúdos não representam cursos já lançados.</div><div class="course-grid">${courses.map((c,i)=>{const n=c.lessons.filter((_,j)=>state.completed.includes(c.id+'-'+j)).length;return `<article class="panel course-card"><div class="course-cover">${ic(c.icon)}<span>0${i+1}</span></div><span class="eyebrow" style="display:block;margin-top:19px">${c.category}</span><h3>${c.title}</h3><p>${c.desc}</p><div class="course-meta"><span>${c.lessons.length} leituras · Exercício prático</span><span>${n}/${c.lessons.length} concluídas</span></div><div class="progress" aria-label="${n} de ${c.lessons.length} leituras concluídas"><i style="width:${n/c.lessons.length*100}%"></i></div><button class="btn full outline" data-course="${c.id}">${n?'Continuar aprendendo':'Conhecer a trilha'} ${ic('arrow')}</button></article>`}).join('')}</div>`}
const bible={
 'Salmos':{'23':[['1','O SENHOR é o meu pastor; nada me faltará.'],['2','Deitar-me faz em verdes pastos, guia-me mansamente a águas tranquilas.'],['3','Refrigera a minha alma; guia-me pelas veredas da justiça por amor do seu nome.'],['4','Ainda que eu andasse pelo vale da sombra da morte, não temeria mal algum, porque tu estás comigo; a tua vara e o teu cajado me consolam.'],['5','Preparas uma mesa perante mim na presença dos meus inimigos, unges a minha cabeça com óleo, o meu cálice transborda.'],['6','Certamente que a bondade e a misericórdia me seguirão todos os dias da minha vida; e habitarei na casa do SENHOR por longos dias.']]},
 'Provérbios':{'3':[['5','Confia no SENHOR de todo o teu coração, e não te estribes no teu próprio entendimento.'],['6','Reconhece-o em todos os teus caminhos, e ele endireitará as tuas veredas.']]}}
;let book='Salmos';
function biblePage(){const chapter=Object.keys(bible[book])[0];return heading('FÉ NO DIA A DIA','Seu momento de paz.','Leia, reflita e leve um princípio para a vida.')+`<div class="two-col"><section class="panel reader"><div class="reader-tools"><label class="field">Livro<select id="bible-book">${Object.keys(bible).map(b=>`<option ${book===b?'selected':''}>${b}</option>`).join('')}</select></label><label class="field">${book==='Salmos'?'Salmo':'Capítulo'}<select aria-label="${book==='Salmos'?'Salmo':'Capítulo'}"><option>${chapter}</option></select></label><span class="badge">Almeida · amostra de leitura</span></div><p class="note">Leitor demonstrativo com Salmo 23 e Provérbios 3:5–6. A Bíblia completa será uma integração futura.</p><h2>${book==='Salmos'?'O cuidado do Pastor':'Confiança e direção'}</h2><div class="bible-copy">${bible[book][chapter].map(([v,t])=>`<p><sup>${v}</sup>${t}</p>`).join('')}</div><div class="reader-action"><span class="eyebrow">DA LEITURA À PRÁTICA</span><h3>${book==='Salmos'?'Como posso cuidar de alguém hoje?':'Que decisão preciso tomar com mais sabedoria?'}</h3><label class="field">Minha reflexão<textarea id="reflection" placeholder="Escreva uma ação simples para o seu dia…">${esc(state.reflection)}</textarea></label><button class="btn" data-action="save-reflection">Salvar reflexão ${ic('check')}</button><p class="note">Anotação pessoal salva apenas neste navegador.</p></div></section><aside>${wordCard()}<section class="panel" style="margin-top:20px"><h3>Um bom começo de dia.</h3><p>Escolha o horário em que gostaria de receber a Palavra do dia.</p>${goButton('notificacoes','Configurar lembrete','bell','btn outline full')}</section></aside></div>`}
let impactView='contribuicoes';
function impact(){return heading('ESCOLHAS QUE VIRAM CUIDADO','Cada escolha<br>deixa uma marca.','Acompanhe de onde vem e aonde chega o bem.')+`<section class="impact-overview"><div><span class="eyebrow">CONTRIBUIÇÕES DA COMUNIDADE</span><div class="impact-value">R$ 248<span>,90</span></div><p>Impacto acumulado · Dados de demonstração</p><div class="impact-tags"><span>${ic('store')} 3 registros</span><span>${ic('heart')} 1 projeto apoiado</span></div></div><div class="impact-chart"><div class="chart-head"><span>Pequenas escolhas, ao longo do caminho.</span>${ic('leaf')}</div><svg viewBox="0 0 320 110" role="img" aria-label="Ilustração do crescimento do impacto acumulado"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b8dd89" stop-opacity=".22"/><stop offset="1" stop-color="#b8dd89" stop-opacity="0"/></linearGradient></defs><path d="M0 100C20 100 27 92 47 91S65 72 90 74 115 70 130 59 150 61 170 48 190 52 210 35 237 43 255 23 285 28 312 7V110H0Z" fill="url(#chart-fill)" stroke="none"/><path d="M0 100C20 100 27 92 47 91S65 72 90 74 115 70 130 59 150 61 170 48 190 52 210 35 237 43 255 23 285 28 312 7" stroke="#c5e7a0" stroke-width="2" fill="none"/><circle cx="312" cy="7" r="4" fill="#d4f5b1" stroke="#57804e" stroke-width="4"/></svg><small>Representação ilustrativa · Sem transações reais</small></div></section><div class="two-col impact-layout"><section><div class="section-head"><h2>O caminho do seu impacto</h2></div><div class="statement-tabs" aria-label="Registros de impacto"><button data-impact-view="contribuicoes" aria-pressed="${impactView==='contribuicoes'}" class="${impactView==='contribuicoes'?'selected':''}">Contribuições <span>3</span></button><button data-impact-view="notas" aria-pressed="${impactView==='notas'}" class="${impactView==='notas'?'selected':''}">Minhas notas <span>${state.receipts.length}</span></button></div><div class="panel statement-panel">${impactView==='contribuicoes'?`<div class="statement-label">ORIGEM → PROJETO APOIADO</div>${[['Pão & Prosa','Compra de R$ 90,00 · 5% ilustrativos','4.50','food'],['Estúdio Raízes','Compra de R$ 1.000,00 · 8% ilustrativos','80','bag'],['Histórico anterior','Contribuições agrupadas de exemplo','164.40','heart']].map(([n,d,v,i])=>`<article class="statement-row"><span class="statement-icon">${ic(i)}</span><div><strong>${n}</strong><small>${d}</small><span class="statement-destination">${ic('arrow')} Projeto Sementes</span></div><div class="statement-amount"><strong>${money(v)}</strong><small>Repasse de exemplo</small></div></article>`).join('')}<p class="note">Origem, valor e destino visíveis. Estes exemplos não correspondem a compras ou repasses reais.</p>`:`${state.receipts.length?state.receipts.map(r=>`<article class="statement-row"><span class="statement-icon">${ic('receipt')}</span><div><strong>${esc(r.business)}</strong><small>Compra: ${money(r.amount)}</small><span class="statement-destination">${ic('arrow')} ${esc(r.project)}</span><span class="pending-tag">Aguardando validação</span></div><div class="statement-amount"><strong>${money(r.amount*r.rate/100)}</strong><small>Potencial ilustrativo</small></div></article>`).join(''):'<div class="empty-note">'+ic('receipt')+'<h3>Uma nota pode ir mais longe.</h3><p>Depois de comprar de uma empresa parceira, registre sua nota e acompanhe o processo.</p>'+goButton('nota','Enviar minha primeira nota','scan')+'</div>'}<p class="note">O registro não confirma repasse. A compra precisa ser validada pela empresa na versão real.</p>`}</div>${impactView==='contribuicoes'?'<div class="impact-transparency">'+ic('eye')+'<span><strong>Transparência em cada etapa.</strong><small>A contribuição vem da empresa parceira. Você não paga a mais e não recebe saldo para saque.</small></span></div>':''}</section><aside class="panel project-panel"><div class="project-symbol">${ic('leaf')}</div><span class="eyebrow">UM DESTINO PARA O BEM</span><h2>Qual história você<br>quer fortalecer?</h2><p>Escolha o projeto das suas próximas notas.</p><form id="project-form">${[['Projeto Sementes','Educação e cuidado com crianças.'],['Mesa Compartilhada','Alimento e acolhimento de famílias.'],['Recomeçar','Capacitação para novos começos.']].map(([p,d])=>`<label class="project-choice"><input type="radio" name="project" value="${p}" ${state.project===p?'checked':''}><span>${p}<small>${d}</small></span></label>`).join('')}<button class="btn full">Salvar escolha ${ic('check')}</button></form><p class="note">Projetos fictícios. As notas já registradas mantêm o destino escolhido.</p></aside></div>`}
function receipt(){return heading('SUA COMPRA PODE IR MAIS LONGE','Sua compra vai além.','Compre diretamente com a empresa parceira e registre sua compra.')+`<div class="two-col"><div class="panel"><div class="sample-banner">Simulação local. Nenhuma imagem é enviada e nenhum repasse é realizado.</div><div class="capture-intro"><div class="capture-frame">${ic('scan')}</div><div><strong>Da sua compra para um propósito.</strong><p>Escolha a empresa e adicione a nota.<br>A gente mostra o próximo passo.</p></div></div><form id="receipt-form"><label class="field">Empresa parceira<select name="business" id="receipt-business">${businesses.map(b=>`<option value="${b.id}">${b.name} · ${b.rate}% ilustrativos</option>`).join('')}</select></label><label class="field">Valor da compra (R$)<input name="amount" id="receipt-amount" type="number" min="0.01" max="1000000" step="0.01" value="90" required inputmode="decimal"></label><label class="field">Foto da nota (opcional no protótipo)<input name="receipt" type="file" accept="image/*,application/pdf"></label><p class="note">Somente o nome do arquivo é guardado no navegador. A imagem permanece no seu dispositivo.</p><label class="field">Projeto apoiado<select name="project">${['Projeto Sementes','Mesa Compartilhada','Recomeçar'].map(p=>`<option ${state.project===p?'selected':''}>${p}</option>`).join('')}</select></label><div class="saved" id="receipt-estimate">Contribuição potencial da empresa: <strong>R$ 4,50</strong></div><p class="note">Percentuais de exemplo. Sujeito à validação da empresa. Você não recebe cashback nem saldo resgatável.</p><button type="submit" class="btn full">Simular envio da nota ${ic('arrow')}</button></form></div><aside><div class="panel"><span class="eyebrow">UM CAMINHO TRANSPARENTE</span><h2 style="margin-top:18px">Como a compra<br>vira impacto.</h2>${[['01','Você compra','Pelo mesmo preço, diretamente com a empresa.'],['02','A compra é validada','A empresa confirma a nota e o valor elegível.'],['03','A empresa contribui','Uma parte é destinada ao projeto escolhido.'],['04','Você acompanha','A origem, o valor e o destino ficam visíveis.']].map(([n,t,d])=>`<div class="ledger-row"><span class="eyebrow">${n}</span><div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}</div></aside></div>`}
function community(){const events=[['cafe','Café com quem empreende','Uma roda de conversa para apresentar seu negócio, trocar experiências e descobrir parcerias.','Encontro presencial · Recife · Data a definir'],['gestao','Negócios com propósito','Conversa sobre gestão, serviço e os desafios de empreender com valores.','Encontro online · Data a definir']];return heading('RELAÇÕES QUE CRESCEM FORA DA TELA','Bom ter com<br>quem caminhar.','Encontros para aprender, compartilhar e construir confiança.')+'<div class="sample-banner">Agenda conceitual: estes encontros ainda não estão agendados. O interesse é registrado somente neste navegador.</div><div class="mural-grid">'+events.map(([id,t,d,when])=>'<article class="panel post"><span class="badge">Encontro proposto</span><h3>'+t+'</h3><p>'+d+'</p><p>'+when+'</p><button class="btn outline" data-event="'+id+'">'+((state.events||[]).includes(id)?'Interesse registrado · cancelar':'Tenho interesse')+'</button></article>').join('')+'</div><section class="panel" style="margin-top:24px"><h2>Comece por uma boa conversa.</h2><p>Encontre pessoas da sua área no mural. Cada necessidade e oferta pode ser o começo de uma parceria.</p>'+goButton('mural','Conhecer o mural')+'</section>'}
function notifications(){return heading('UMA PALAVRA, UM NOVO OLHAR','Uma palavra.<br>Um novo olhar.','Personalize seu momento de leitura e reflexão.')+`<div class="two-col"><div><article class="panel notification">${ic('book')}<div><h3>Palavra do dia · Prévia</h3><p>“Tudo o que fizerem, façam de todo o coração.” Colossenses 3:23, trecho.</p><small>Na prática: coloque cuidado em uma tarefa que costuma fazer no automático.</small><div style="margin-top:18px">${goButton('biblia','Abrir reflexão','arrow','text-btn')}</div></div></article><article class="panel notification">${ic('mural')}<div><h3>Sua comunidade tem oportunidades.</h3><p>Conheça necessidades e serviços no mural e registre sua próxima conexão.</p>${goButton('mural','Explorar o mural','arrow','text-btn')}</div></article></div><form class="panel" id="notification-form"><h3>Meu lembrete diário</h3><label class="settings-row"><span><strong>Receber a Palavra do dia</strong><small>Preferência de demonstração</small></span><input type="checkbox" name="notify" ${state.notify?'checked':''}></label><label class="field">Horário preferido<input type="time" name="time" required value="${esc(state.notifyTime)}"></label><p>O protótipo salva sua preferência e mostra a prévia acima. Notificações reais, inclusive com o app fechado, dependem da implementação futura.</p><button class="btn full">Salvar preferência ${ic('check')}</button></form></div>`}
function profile(){return heading('BEM-VINDA À COMUNIDADE','Do seu jeito.','Um perfil claro ajuda as pessoas certas a encontrar você.')+`<div class="two-col"><form class="panel" id="profile-form"><span class="profile-mark">${esc(state.profile.name[0])}</span><label class="field">Seu nome<input name="name" maxlength="80" required value="${esc(state.profile.name)}" autocomplete="name"></label><label class="field">Empresa<input name="business" value="${esc(state.profile.business)}" maxlength="100" placeholder="Como se chama seu negócio?"></label><label class="field">Cidade<input name="city" required maxlength="80" value="${esc(state.profile.city)}"></label><button class="btn">Salvar perfil ${ic('check')}</button><p class="note">Perfil de demonstração, salvo apenas neste navegador.</p></form><aside class="panel" style="height:max-content"><span class="eyebrow">SOMOS A CRIS</span><h2 style="margin-top:18px">Conectar para<br>fortalecer.</h2><p>Aproximamos quem compra de quem empreende para o Reino. Acreditamos em oportunidade, em boas empresas e em transparência.</p><p>O app reúne negócios, capacitação e fé para gerar relações de confiança e impacto social.</p><button class="btn outline full" data-action="reset">Reiniciar demonstração</button><p class="note">Remove somente os dados deste protótipo neste navegador.</p></aside></div>`}
function render(){document.querySelector('#main').classList.remove('product-screen');document.body.dataset.page=route;document.title=`CRIS — ${nav.find(n=>n[0]===route)?.[2]||({nota:'Enviar nota',perfil:'Meu perfil',notificacoes:'Palavra do dia'}[route])||'Início'}`;$('#nav').innerHTML=nav.map(([r,i,t])=>`<a class="nav-item ${route===r?'active':''}" href="#${r}" ${route===r?'aria-current="page"':''}>${ic(i)}<span>${t}</span>${r==='mural'?`<span class="count">${state.posts.length+4}</span>`:''}</a>`).join('');$('#mobile-nav').innerHTML=[['inicio','home','Início'],['empresas','store','Explorar'],['nota','scan','Enviar nota'],['mural','connect','Conectar']].map(([r,i,t])=>`<a href="#${r}" class="${route===r?'active':''} ${r==='nota'?'scan-nav':''}" ${route===r?'aria-current="page"':''}><span class="nav-icon">${ic(i)}</span><span>${t}</span></a>`).join('')+`<button data-action="more" class="${!['inicio','empresas','nota','mural'].includes(route)?'active':''}" aria-label="Mais opções"><span class="nav-icon">${ic('more')}</span><span>Mais</span></button>`;$('#bell').innerHTML=ic('bell')+'<i></i>';const screens={inicio:home,empresas:market,mural,conexoes:connections,comunidade:community,cursos:coursePage,biblia:biblePage,impacto:impact,nota:receipt,notificacoes:notifications,perfil:profile};$('#main').innerHTML=(screens[route]||home)();$('.side-profile>span:nth-child(2)').innerHTML=`${esc(state.profile.name)}<small>Minha conta · Demonstração</small>`;document.querySelectorAll('.avatar[data-route="perfil"],.side-profile .avatar').forEach(a=>a.textContent=state.profile.name[0]);if(typeof enhanceScreen==='function')enhanceScreen();}

function navigate(r){if(route===r){render();return}location.hash=r}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'inicio';filter=pendingCategory||'Todos';pendingCategory=null;render();window.scrollTo({top:0,left:0,behavior:"instant"});$('#main').focus({preventScroll:true})});
function openModal(title,body){$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-top"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Fechar">${ic('close')}</button></div>${body}</div>`;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function showBusiness(id){const b=businesses.find(x=>x.id===id);openModal(b.name,`${art(b)}<span class="eyebrow">${b.category} · EMPRESA DE DEMONSTRAÇÃO</span><p>${b.desc}</p><div class="detail-grid"><div><small>PRODUTOS E SERVIÇOS</small><strong>${b.products}</strong></div><div><small>ONDE ESTAMOS</small><strong>${b.city}</strong></div><div><small>QUEM EMPREENDE</small><strong>${b.owner}</strong></div><div><small>ATENDIMENTO</small><strong>${b.hours}</strong></div></div><div class="saved">${b.rate}% ilustrativos para o projeto escolhido. Contribuição da empresa após validação da compra.</div><p>Na versão real, o contato será pelo canal informado pela empresa. Você negocia e compra diretamente com ela.</p><button class="btn full" data-biz-connect="${b.id}">Registrar interesse no negócio ${ic('connect')}</button><p class="note">Nenhum contato real é feito. Não há checkout ou pagamento neste protótipo.</p>`)}
function newPost(){openModal('Uma boa conexão começa aqui.',`<form id="post-form"><label class="field">O que você quer publicar?<select name="type"><option>Preciso</option><option>Posso oferecer</option></select></label><label class="field">Título<input name="title" required maxlength="100" placeholder="Do que você precisa ou o que oferece?"></label><label class="field">Conte um pouco mais<textarea name="description" required maxlength="700" placeholder="Dê detalhes para facilitar a conexão."></textarea></label><label class="field">Área ou categoria<input name="area" required maxlength="80" placeholder="Ex.: Marketing · Online"></label><p class="note">Publicação local, visível somente neste navegador.</p><button class="btn full">Publicar no mural ${ic('arrow')}</button></form>`)}
function addConnection(postId){const p=[...state.posts,...samplePosts].find(p=>p.id===postId);if(state.connections.some(c=>c.postId===postId)){navigate('conexoes');return}openModal('Uma oportunidade de conversar.',`<p>Você está demonstrando interesse em <strong>${esc(p.title)}</strong>, de ${esc(p.author)}.</p><p>O próximo passo seria uma conversa pelo canal autorizado pelo membro. No protótipo, você pode registrar e acompanhar essa conexão.</p><button class="btn full" data-confirm-connect="${esc(postId)}">Registrar conexão ${ic('connect')}</button>`)}
function showCourse(id,index){const c=courses.find(c=>c.id===id);if(index===undefined)index=c.lessons.findIndex((_,j)=>!state.completed.includes(id+'-'+j));if(index<0)index=0;const [title,text,exercise]=c.lessons[index];openModal(c.title,`<span class="eyebrow">LEITURA ${index+1} DE ${c.lessons.length} · CONTEÚDO DEMONSTRATIVO</span><div class="lesson"><h3>${title}</h3><p>${text}</p><div class="saved"><strong>Coloque em prática</strong><p>${exercise}</p></div></div><div class="row">${c.lessons.map((_,j)=>`<button class="chip ${j===index?'selected':''}" data-lesson="${id}:${j}">${j+1}${state.completed.includes(id+'-'+j)?' ✓':''}</button>`).join('')}</div><button class="btn full" style="margin-top:20px" data-complete="${id}:${index}">${state.completed.includes(id+'-'+index)?'Leitura concluída · continuar':'Concluir leitura e continuar'} ${ic('check')}</button>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.category){query='';onlyFavorites=false;if(route==='empresas'){filter=b.dataset.category;render()}else{pendingCategory=b.dataset.category;navigate('empresas')}}if(b.dataset.favorite){state.favorites=state.favorites||[];const id=b.dataset.favorite;const exists=state.favorites.includes(id);state.favorites=exists?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();b.classList.toggle('is-saved',!exists);b.setAttribute('aria-pressed',String(!exists));const biz=businesses.find(x=>x.id===id);b.setAttribute('aria-label',(exists?'Salvar ':'Remover ')+biz.name);if(onlyFavorites)$('#market-results').innerHTML=marketResults();toast(exists?'Negócio removido dos seus salvos.':'Salvo para você encontrar depois.')}if(b.dataset.route){if($('#modal').open)closeModal();navigate(b.dataset.route)}if(b.dataset.business)showBusiness(b.dataset.business);if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.postFilter){filter=b.dataset.postFilter;render()}if(b.dataset.connect)addConnection(b.dataset.connect);if(b.dataset.confirmConnect){const p=[...state.posts,...samplePosts].find(p=>p.id===b.dataset.confirmConnect);state.connections.push({id:'c'+Date.now(),postId:p.id,person:p.author,title:p.title,status:'Interesse registrado'});save();closeModal();navigate('conexoes');toast('Conexão registrada na demonstração.')}if(b.dataset.bizConnect){const biz=businesses.find(x=>x.id===b.dataset.bizConnect);if(!state.connections.some(c=>c.postId==='biz-'+biz.id)){state.connections.push({id:'c'+Date.now(),postId:'biz-'+biz.id,person:biz.name,title:biz.products,status:'Interesse registrado'});save()}closeModal();navigate('conexoes');toast('Interesse registrado. Nenhuma mensagem foi enviada.')}if(b.dataset.event){state.events=state.events||[];state.events=state.events.includes(b.dataset.event)?state.events.filter(id=>id!==b.dataset.event):[...state.events,b.dataset.event];save();render();toast('Preferência de encontro atualizada neste navegador.')}if(b.dataset.impactView){impactView=b.dataset.impactView;render()}if(b.dataset.course)showCourse(b.dataset.course);if(b.dataset.lesson){const [id,j]=b.dataset.lesson.split(':');showCourse(id,Number(j))}if(b.dataset.complete){const [id,j]=b.dataset.complete.split(':');const key=id+'-'+j;if(!state.completed.includes(key))state.completed.push(key);save();const c=courses.find(c=>c.id===id);if(Number(j)+1<c.lessons.length)showCourse(id,Number(j)+1);else{closeModal();render();toast('Trilha de demonstração concluída. Bom aprendizado!')}}switch(b.dataset.action){case'toggle-impact':state.hideImpact=!state.hideImpact;save();render();document.querySelector('.pass-eye').focus({preventScroll:true});break;case'filter-favorites':onlyFavorites=!onlyFavorites;render();break;case'location':openModal('Sua comunidade por perto',`<p>A localização vem da cidade informada no seu perfil. No protótipo, as empresas são exemplos de Recife e região.</p>${goButton('perfil','Atualizar minha cidade','pin','btn full')}`);break;case'close':closeModal();break;case'new-post':newPost();break;case'save-reflection':state.reflection=$('#reflection').value;save();toast('Reflexão salva neste navegador.');break;case'more':openModal('Mais possibilidades.',`<p class="more-intro">Seu negócio, sua comunidade e um momento para você.</p><div class="mobile-more">${nav.filter(n=>['impacto','cursos','biblia','conexoes','comunidade'].includes(n[0])).map(([r,i,t])=>goButton(r,t,i,'btn outline')).join('')}${goButton('notificacoes','Palavra do dia e lembretes','bell','btn outline')}${goButton('perfil','Meu perfil','user','btn outline')}</div>`);break;case'reset':openModal('Reiniciar a demonstração?',`<p>Isso remove suas notas simuladas, publicações, conexões, reflexões e preferências deste navegador.</p><button class="btn full" data-action="confirm-reset">Reiniciar demonstração</button>`);break;case'confirm-reset':state=structuredClone(defaults);save();closeModal();navigate('inicio');toast('Demonstração reiniciada.');break;}});
document.addEventListener('input',e=>{if(e.target.id==='market-search'){query=e.target.value;$('#market-results').innerHTML=marketResults()}if(['receipt-amount','receipt-business'].includes(e.target.id)){const amount=Number($('#receipt-amount').value)||0;const biz=businesses.find(b=>b.id===$('#receipt-business').value);$('#receipt-estimate').innerHTML=`Contribuição potencial da empresa: <strong>${money(amount*biz.rate/100)}</strong>`}});
document.addEventListener('change',e=>{if(e.target.dataset.status){state.connections.find(c=>c.id===e.target.dataset.status).status=e.target.value;save();render();toast('Etapa da conexão atualizada.')}if(e.target.id==='bible-book'){book=e.target.value;render()}});
document.addEventListener('submit',e=>{const form=e.target;const supported=['home-search-form','post-form','receipt-form','project-form','notification-form','profile-form'];if(!supported.includes(form.id))return;e.preventDefault();const f=new FormData(form);switch(form.id){case'home-search-form':query=String(f.get('q')||'').trim();onlyFavorites=false;navigate('empresas');break;case'post-form':{const title=f.get('title').trim(),description=f.get('description').trim(),area=f.get('area').trim();if(!title||!description||!area){toast('Preencha os campos com os detalhes da publicação.');return}state.posts.unshift({id:'p'+Date.now(),type:f.get('type'),title,description,area,author:state.profile.name,initial:state.profile.name[0]});save();closeModal();filter='Todos';render();toast('Publicação salva no mural deste navegador.');break}case'receipt-form':{const amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0||amount>1000000)return;const biz=businesses.find(b=>b.id===f.get('business'));state.receipts.unshift({business:biz.name,amount,rate:biz.rate,project:f.get('project'),filename:f.get('receipt')?.name||''});save();impactView='notas';navigate('impacto');toast('Nota simulada registrada. Aguardando validação.');break}case'project-form':state.project=f.get('project');save();render();toast('Projeto escolhido para as próximas notas.');break;case'notification-form':state.notify=f.has('notify');state.notifyTime=f.get('time');save();render();toast('Preferência salva. Lembretes reais ainda não estão ativos.');break;case'profile-form':{const name=f.get('name').trim(),city=f.get('city').trim();if(!name||!city){toast('Informe seu nome e sua cidade.');return}state.profile={name,city,business:f.get('business').trim()};save();render();toast('Perfil atualizado neste navegador.');break}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
route=location.hash.slice(1)||'inicio';render();

document.addEventListener('scroll',e=>{if(e.target.classList?.contains('moment-rail')){const dots=document.querySelectorAll('.carousel-position i');const active=e.target.scrollLeft>e.target.clientWidth/3?1:0;dots.forEach((dot,i)=>{dot.style.width=i===active?'15px':'4px';dot.style.background=i===active?'#557c52':'#d8dfd1'})}},true);
